### Description

The below works with:
```
    model: gateway('openai/gpt-4o-mini'),
```

Sample code:
```
import { generateObject } from 'ai';
import { gateway } from '@vercel/ai-sdk-gateway';
import 'dotenv/config';
import { z } from 'zod';

async function main() {
  const prompt = 'I want to know the traffic data for the last 1.5 hours';
  const { object: timeParams } = await generateObject({
    model: gateway('anthropic/claude-3.7-sonnet'),
    schema: z.object({
      startTime: z
        .string()
        .describe('The start time for traffic data analysis'),
      endTime: z.string().describe('The end time for traffic data analysis'),
    }),
    prompt: `Extract only the time period information from the following request. If no specific time is mentioned, use the last 24 hours: "${prompt}"`,
    mode: 'tool',
  });

  console.log(timeParams);
}

main().catch(console.error);
```

